css:
body{font-family:"Anthropic Sans","Styrene B",ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;}
.chat-markdown{font-family:"Anthropic Serif","Tiempos Text",Charter,"Iowan Old Style",Georgia,serif;}
.chat-markdown code,.chat-markdown-codeblock,.chat-markdown pre{font-family:"Anthropic Mono",ui-monospace,"SF Mono",Menlo,Consolas,monospace;}
[data-thread-item]{border-radius:8px!important;}
[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"]{border-radius:8px!important;}
[data-slot="composer-host"]{border-radius:20px!important;border:1px solid var(--border)!important;box-shadow:0 4px 20px rgba(0,0,0,.035)!important;}
.dark [data-slot="composer-host"]{box-shadow:0 4px 20px rgba(0,0,0,.18)!important;}
[data-slot="composer-host"]:focus-within{border-color:color-mix(in srgb,var(--foreground) 28%,transparent)!important;}
[data-user-message-bubble]{border-radius:12px!important;}
.chat-markdown-codeblock{border-radius:8px!important;border:1px solid var(--border);}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:12px!important;border:1px solid var(--border)!important;box-shadow:0 8px 28px rgba(0,0,0,.08)!important;}
[data-slot="tooltip-popup"]{border-radius:6px!important;}
button.bg-message-action{border-radius:10px!important;}
button.bg-message-action:disabled{background:color-mix(in srgb,#C6613F 45%,transparent)!important;color:#FFFFFF!important;opacity:1!important;}
.dark [data-slot="switch"][data-unchecked]{background:#3A3935!important;box-shadow:none!important;}
.dark [data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#C2C0B6!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#DEDCD1!important;box-shadow:none!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
[data-slot="switch"][data-checked]{background:#C6613F!important;box-shadow:none!important;}
[data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 15%,transparent);border-radius:999px;border:2px solid transparent;background-clip:padding-box;}
::selection{background:color-mix(in srgb,#D97757 30%,transparent);}
